// --------------------------------------------------------
// IMAGE (FINAL PASS)
// --------------------------------------------------------
// iChannel0 => Buffer A
// iChannel1 => Buffer B
// iChannel2 => Buffer C
// iChannel3 => Buffer D
//
// Minkowski Voronoi, with time-varying radii.

#define VERTEX_RADIUS 1.5

//-----------------------------------
// HELPER FUNCTIONS
//-----------------------------------

ivec2 locFromID(int id)
{
    int w = int(iResolution.x);
    return ivec2(id % w, id / w);
}

vec4 getParticle(int id)
{
    return texelFetch(iChannel0, locFromID(id), 0);
}
float getRadius(int id)
{
    return texelFetch(iChannel3, locFromID(id), 0).r;
}

// Periodic distance
float periodicDist(vec2 a, vec2 b)
{
    vec2 d = a - b;
    d = mod(d + 0.5*iResolution.xy, iResolution.xy) - 0.5*iResolution.xy;
    return length(d);
}

// Periodic delta
vec2 periodicDelta(vec2 delta)
{
    return mod(delta + 0.5*iResolution.xy, iResolution.xy) - 0.5*iResolution.xy;
}

// gather 4 candidate IDs from Buffer B
ivec4 getClosest4(ivec2 c)
{
    ivec2 res = ivec2(iResolution.xy);
    c = ivec2((c.x + res.x) % res.x, (c.y + res.y) % res.y);
    return ivec4(texelFetch(iChannel1, c, 0));
}

// (distance - radius)
float getMeasure(vec2 P, int siteID)
{
    vec2 center = getParticle(siteID).xy;
    float rad   = getRadius(siteID);
    float dist  = periodicDist(P, center);
    return dist - rad;
}

// pick site with minimal (dist - radius)
int getNearestID(ivec2 c)
{
    ivec4 four = getClosest4(c);
    float bestVal = 1e20;
    int   bestID  = -1;
    vec2  fc      = vec2(c);

    for(int i=0; i<4; i++)
    {
        int candidateID = four[i];
        if(candidateID < 0) continue;

        float val = getMeasure(fc, candidateID);
        if(val < bestVal)
        {
            bestVal = val;
            bestID  = candidateID;
        }
    }
    return bestID;
}

int countDistinctSites(ivec2 center)
{
    int arr[9];
    int index = 0;
    for(int dy=-1; dy<=1; dy++){
        for(int dx=-1; dx<=1; dx++){
            ivec2 c = center + ivec2(dx, dy);
            c = clamp(c, ivec2(0), ivec2(iResolution.xy)-ivec2(1));
            arr[index++] = getNearestID(c);
        }
    }

    int distinct = 0;
    for(int i=0; i<9; i++){
        bool isNew = true;
        for(int j=0; j<i; j++){
            if(arr[i] == arr[j]){
                isNew = false;
                break;
            }
        }
        if(isNew) distinct++;
    }
    return distinct;
}

// Simple random grey
float randomGrey(int siteID)
{
    float r = fract(sin(float(siteID) * 78.233) * 43758.5453);
    return 0.3 + 0.02 * r;
}

//-----------------------------------
// MAIN
//-----------------------------------
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    ivec2 pc  = ivec2(fragCoord);
    int   sid = getNearestID(pc);

    // 1) base color
    float grey = randomGrey(sid);
    vec4 baseLayer = vec4(vec3(grey), 1.0);

    // 2) secondDist from Buffer C
    float secondDist = texelFetch(iChannel2, locFromID(sid), 0).x;

    // 3) blue tint
    float maxSize   = length(iResolution.xy) * 0.125;
    float sizeRatio = clamp(secondDist / maxSize, 0.0, 1.0);
    vec4 blueLayer  = vec4(0.0, 0.0, 0.1, 0.8 * (1.0 - sizeRatio));
    vec4 color      = mix(baseLayer, blueLayer, blueLayer.a);

    // 4) partial transparency circle highlight
    vec2 sitePos   = getParticle(sid).xy;
    float siteRad  = getRadius(sid);
    float distToSite = periodicDist(fragCoord, sitePos);
    float dmr      = distToSite - siteRad;

    float highlight = smoothstep(2.0, 0.0, dmr);
    float alpha     = 0.1 * highlight;   // up to 30% in center
    color.rgb       = mix(color.rgb, vec3(1.0), alpha);

    // 5) Light edge highlight (derivative-based)
    float edge = smoothstep(0.0, 1.0, abs(dFdx(grey)) + abs(dFdy(grey)));
    color.rgb  = mix(color.rgb, vec3(0.0), edge);

    // 6) corner detection
    int dCount = countDistinctSites(pc);
    if(dCount >= 3)
    {
        ivec4 c4 = getClosest4(pc);
        int ids[4] = int[4](c4[0], c4[1], c4[2], c4[3]);

        int uniqueIDs[3];
        int uniqCount = 0;
        for(int i=0; i<4 && uniqCount<3; i++){
            bool isNew = true;
            for(int j=0; j<uniqCount; j++){
                if(ids[i] == uniqueIDs[j]){
                    isNew = false;
                    break;
                }
            }
            if(isNew){
                uniqueIDs[uniqCount++] = ids[i];
            }
        }
        if(uniqCount < 3)
        {
            fragColor = color;
            return;
        }

        int id0 = uniqueIDs[0];
        int id1 = uniqueIDs[1];
        int id2 = uniqueIDs[2];

        vec2 A = getParticle(id0).xy;
        vec2 B = getParticle(id1).xy;
        vec2 C = getParticle(id2).xy;

        vec2 AB = periodicDelta(B - A);
        vec2 AC = periodicDelta(C - A);
        vec2 BA = periodicDelta(A - B);
        vec2 BC = periodicDelta(C - B);
        vec2 CA = periodicDelta(A - C);
        vec2 CB = periodicDelta(B - C);

        bool obtuseA = dot(AB, AC) < 0.0;
        bool obtuseB = dot(BA, BC) < 0.0;
        bool obtuseC = dot(CA, CB) < 0.0;

        vec2 vertexPos;
        if(!obtuseA && !obtuseB && !obtuseC)
        {
            // circumcenter
            vec2 midAB = A + 0.5*AB;
            vec2 midAC = A + 0.5*AC;
            vec2 dirAB = vec2(-AB.y, AB.x);
            vec2 dirAC = vec2(-AC.y, AC.x);

            mat2 M   = mat2(dirAB, -dirAC);
            vec2 rhs = midAC - midAB;
            float det = M[0][0]*M[1][1] - M[0][1]*M[1][0];
            if(abs(det) > 1e-4)
            {
                vec2 t = (1.0/det) * vec2(
                    M[1][1]*rhs.x - M[0][1]*rhs.y,
                    -M[1][0]*rhs.x + M[0][0]*rhs.y
                );
                vertexPos = midAB + t.x * dirAB;
            }
            else
            {
                vertexPos = (A + B + C) / 3.0;
            }
        }
        else
        {
            // midpoint of opposite side
            if(obtuseA){
                vertexPos = B + 0.5*BC;
            } else if(obtuseB){
                vertexPos = A + 0.5*AC;
            } else {
                vertexPos = A + 0.5*AB;
            }
        }

        vertexPos = mod(vertexPos + 0.5*iResolution.xy, iResolution.xy) - 0.5*iResolution.xy;

        float vertexDist = periodicDist(fragCoord, vertexPos);
        if(vertexDist < VERTEX_RADIUS)
        {
            // If any angle obtuse => red, else green
            color.rgb = (obtuseA || obtuseB || obtuseC)
                        ? vec3(1.0, 0.0, 0.0)
                        : vec3(0.000,0.667,1.000);
        }
    }

    fragColor = color;
}

// --------------------------------------------------------
// COMMON TAB
// --------------------------------------------------------
//
// Shadertoy automatically provides iResolution, iTime, iMouse, etc.
//
// We define the following constants and a hashing function:

const int   PARTICLES   = 2000;  // total number of particles
const float SPEED       = 2.0;   // max speed in Buffer A
const float RMIN        = 2.0;   // minimum circle radius
const float RMAX        = 5.0;  // maximum circle radius
const float FLUCT_SPEED = 8.0;   // global speed multiplier for radius fluctuation

// IQ's hashing noise using uintBitsToFloat
float hash(int k)
{
    uint n = uint(k);
    n = (n << 13U) ^ n;
    n = n * (n * n * 15731U + 789221U) + 1376312589U;
    return uintBitsToFloat((n >> 9U) | 0x3f800000U) - 1.0;
}

// --------------------------------------------------------
// BUFFER A
// --------------------------------------------------------
// iChannel0 => Buffer A (backbuffer: pos, vel)
// iChannel1 => Buffer B (nearest site IDs)
// iChannel2 => (unused?)
// iChannel3 => Buffer D (for radius if needed)
//
// This code uses Minkowski offset + relaxation logic.

ivec2 locFromID(int id)
{
    int w = int(iResolution.x);
    return ivec2(id % w, id / w);
}

// Periodic wrap delta
vec2 periodicDelta(vec2 delta)
{
    return mod(delta + 0.5*iResolution.xy, iResolution.xy) - 0.5*iResolution.xy;
}

// Accessors
vec4 getParticle(int id) {
    return texelFetch(iChannel0, locFromID(id), 0);
}
float getRadius(int id) {
    // from Buffer D
    return texelFetch(iChannel3, locFromID(id), 0).r;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    ivec2 pix = ivec2(fragCoord);
    int   id  = pix.x + pix.y * int(iResolution.x);

    // If not a valid particle, just copy old data
    if(id >= PARTICLES)
    {
        fragColor = texelFetch(iChannel0, pix, 0);
        return;
    }

    // Load old pos & vel
    vec4 prev = texelFetch(iChannel0, pix, 0);
    vec2 pos  = prev.xy;
    vec2 vel  = prev.zw;

    // First frame init
    if(iFrame == 0)
    {
        float h1 = hash(id);
        float h2 = hash(id + 99999);
        pos = vec2(h1, h2) * iResolution.xy;
        vel = vec2(0.0);
    }

    //--------------------------------
    // 1) Accumulate forces
    //--------------------------------
    vec2 force = vec2(0.0);

    // (a) friction
    force -= vel * 0.3;

    // (b) mouse repulsion (if pressed)
    if(iMouse.z > 0.0)
    {
        vec2 delta = pos - iMouse.xy;
        float dist = length(delta) + 1e-3;
        force += delta / (dist*dist) * 10.0;
    }

    // (c) neighbor repulsion
    // We'll do a "hybrid": baseline point-based push + extra push if overlapping
    float radA = getRadius(id);

    // read the 4 nearest IDs from Buffer B
    ivec2 ipos = ivec2(floor(pos));
    ivec4 closeIDs = ivec4(texelFetch(iChannel1, ipos, 0));

    for(int i=0; i<4; i++)
    {
        int cid = closeIDs[i];
        if(cid < 0 || cid == id) continue;

        vec2  otherPos = getParticle(cid).xy;
        float radB     = getRadius(cid);

        vec2 delta = pos - otherPos;
        delta = periodicDelta(delta);
        float dist = length(delta) + 1e-6;

        // baseline 1/r^3 push
        float factor = 30.0 / (dist * dist * dist);
        force += delta * factor;

        // extra "soft-sphere" if overlap
        float sumRad  = radA + radB;
        float overlap = sumRad - dist;
        if(overlap > 0.0)
        {
            float extra = 30.0 * overlap;
            force += normalize(delta) * extra;
        }
    }

    //--------------------------------
    // 2) Integrate & Wrap
    //--------------------------------
    vel += force;

    // speed cap
    float spd = length(vel);
    if(spd > SPEED) {
        vel *= (SPEED / spd);
    }

    // move & wrap
    pos = mod(pos + vel, iResolution.xy);

    // Store updated (pos, vel)
    fragColor = vec4(pos, vel);
}

// --------------------------------------------------------
// BUFFER B
// --------------------------------------------------------
// iChannel0 => Buffer A (positions)
// iChannel1 => Buffer B (backbuffer)
// iChannel2 => (unused)
// iChannel3 => Buffer D (for radius)

////////////////////////////////////
// HELPER FUNCTIONS
////////////////////////////////////

ivec2 locFromID(int id) {
    int w = int(iResolution.x);
    return ivec2(id % w, id / w);
}

// Retrieve (pos, vel) from Buffer A
vec4 getParticle(int id) {
    return texelFetch(iChannel0, locFromID(id), 0);
}

// measure = distance - radius (Minkowski offset)
float measureParticle(int id, vec2 fragCoord)
{
    if (id < 0) return 1e20;
    vec4 dat  = getParticle(id);
    vec2 p    = dat.xy;

    float rad = texelFetch(iChannel3, locFromID(id), 0).r;  // read radius from Buffer D

    // periodic distance
    vec2 d = p - fragCoord;
    d = mod(d + 0.5 * iResolution.xy, iResolution.xy) - 0.5 * iResolution.xy;
    float dist = length(d);

    return dist - rad;
}

// insertion-sort logic
void insertion_sort(inout ivec4 i, inout vec4 d, int newID, float newVal)
{
    for (int idx = 0; idx < 4; idx++) {
        if (i[idx] == newID) {
            // If newVal is smaller, bubble
            if (newVal < d[idx]) {
                d[idx] = newVal;
                for (int k = idx; k > 0 && d[k] < d[k-1]; k--) {
                    int tmpI = i[k];
                    i[k]     = i[k-1];
                    i[k-1]   = tmpI;

                    float tmpD = d[k];
                    d[k]       = d[k-1];
                    d[k-1]     = tmpD;
                }
            }
            return;
        }
    }

    // normal insertion if not duplicate
    if (newVal < d[0]) {
        i = ivec4(newID, i[0], i[1], i[2]);
        d = vec4(newVal, d[0], d[1], d[2]);
    } else if (newVal < d[1]) {
        i = ivec4(i[0], newID, i[1], i[2]);
        d = vec4(d[0], newVal, d[1], d[2]);
    } else if (newVal < d[2]) {
        i = ivec4(i[0], i[1], newID, i[2]);
        d = vec4(d[0], d[1], newVal, d[2]);
    } else if (newVal < d[3]) {
        i = ivec4(i[0], i[1], i[2], newID);
        d = vec4(d[0], d[1], d[2], newVal);
    }
}

ivec4 getClosestPrev(ivec2 c) {
    return ivec4(texelFetch(iChannel1, c, 0));
}

// periodic wrap coords
ivec2 wrapCoords(ivec2 c) {
    ivec2 res = ivec2(iResolution.xy);
    return ivec2((c.x + res.x) % res.x, (c.y + res.y) % res.y);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    ivec2 c = ivec2(fragCoord);

    // We'll build new 4 IDs
    ivec4 newIDs  = ivec4(-1);
    vec4  newVals = vec4(1e20);

    // 1) Gather from 3x3 block
    for (int dy = -1; dy <= 1; dy++) {
        for (int dx = -1; dx <= 1; dx++) {
            ivec2 cc = wrapCoords(c + ivec2(dx, dy));
            ivec4 four = getClosestPrev(cc); // from previous frame
            for (int i = 0; i < 4; i++) {
                int cand = four[i];
                // Use pixel-center coordinates (vec2(c) + 0.5)
                float val = measureParticle(cand, vec2(c) + 0.5);
                insertion_sort(newIDs, newVals, cand, val);
            }
        }
    }

    // 2) Random candidate
    float h = hash(
        c.x + c.y * int(iResolution.x)
        + iFrame * int(iResolution.x * iResolution.y)
    );
    int rID = int(h * float(PARTICLES));
    float rVal = measureParticle(rID, vec2(c) + 0.5);
    insertion_sort(newIDs, newVals, rID, rVal);

    // 3) Output top 4 IDs
    fragColor = vec4(newIDs);
}

// --------------------------------------------------------
// BUFFER C
// --------------------------------------------------------
// iChannel0 => Buffer A
// iChannel1 => Buffer B
// iChannel2 => (maybe backbuffer for C or not used)
// iChannel3 => Buffer D
//
// We store in .x the Minkowski-based distance to the nearest other site.

ivec2 locFromID(int id)
{
    int w = int(iResolution.x);
    return ivec2(id % w, id / w);
}

vec4 getParticle(int id)
{
    return texelFetch(iChannel0, locFromID(id), 0);
}
float getRadius(int id)
{
    return texelFetch(iChannel3, locFromID(id), 0).r;
}

// Periodic delta
vec2 periodicDelta(vec2 v)
{
    return mod(v + 0.5*iResolution.xy, iResolution.xy) - 0.5*iResolution.xy;
}

// gather 4 candidate IDs from Buffer B
ivec4 getClosest4(ivec2 c)
{
    ivec2 res = ivec2(iResolution.xy);
    c = ivec2((c.x + res.x) % res.x, (c.y + res.y) % res.y);
    return ivec4(texelFetch(iChannel1, c, 0));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    ivec2 coord = ivec2(fragCoord);
    int   id    = coord.x + coord.y*int(iResolution.x);

    // if invalid particle, store 0
    if(id >= PARTICLES)
    {
        fragColor = vec4(0.0);
        return;
    }

    vec2  posA = getParticle(id).xy;
    float radA = getRadius(id);

    // find the Minkowski-dist to the nearest other site
    float bestDist = 1e20;

    // sample a 3x3 block around posA
    ivec2 base = ivec2(floor(posA));
    for(int dy=-1; dy<=1; dy++){
        for(int dx=-1; dx<=1; dx++){
            ivec2 sampleCoords = base + ivec2(dx, dy);
            ivec4 nb = getClosest4(sampleCoords);
            for(int i=0; i<4; i++){
                int nid = nb[i];
                if(nid < 0 || nid == id) continue;

                vec2  posB  = getParticle(nid).xy;
                float radB  = getRadius(nid);
                vec2  delta = periodicDelta(posA - posB);
                float dist  = length(delta);
                // Minkowski offset => dist - (radA + radB)
                float effDist = dist - (radA + radB);

                if(effDist < bestDist){
                    bestDist = effDist;
                }
            }
        }
    }

    fragColor = vec4(bestDist, 0.0, 0.0, 1.0);
}

// --------------------------------------------------------
// BUFFER D
// --------------------------------------------------------
// iChannel0 => Buffer D (backbuffer)
//
// We store for each particle ID in RGBA:
//   .r = current radius (time-varying)
//   .g = phase  (random, remains constant after init)
//   .b = freq   (random, remains constant after init)
//   .a = dummy  (1.0)

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    ivec2 c  = ivec2(fragCoord);
    int   id = c.x + c.y * int(iResolution.x);

    // If outside [0..PARTICLES)
    if (id >= PARTICLES)
    {
        fragColor = vec4(0.0);
        return;
    }

    // fetch old data
    vec4 old = texelFetch(iChannel0, c, 0);

    if(iFrame == 0)
    {
        // On first frame, pick random phase & freq
        float s1    = hash(id + 12345);
        float s2    = hash(id + 98765);

        float phase = 6.2831853 * s1;      // 2*pi * s1
        float freq  = mix(0.2, 1.0, s2);   // or any range you like
        // or freq = 0.5 + 0.5*s2, etc.

        // initial radius
        float initRad = mix(RMIN, RMAX, hash(id + 5555));

        fragColor = vec4(initRad, phase, freq, 1.0);
    }
    else
    {
        // retrieve old phase & freq
        float phase = old.g;
        float freq  = old.b;

        // compute new radius
        // radius(t) = mix(RMIN, RMAX, 0.5 + 0.5*sin(iTime * FLUCT_SPEED * freq + phase))
        float t   = iTime * FLUCT_SPEED; 
        float s   = sin(t*freq + phase);
        float u   = 0.5 + 0.5*s;  // map [-1..1] -> [0..1]
        float rad = mix(RMIN, RMAX, u);

        // keep old phase & freq
        fragColor = vec4(rad, phase, freq, 1.0);
    }
}
